import { test, expect } from '@playwright/test';

test.describe('Search Result Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should highlight search terms in result snippets', async ({ page }) => {
    await page.fill('input[name="search"]', 'Playwright');
    await page.click('button[type="submit"]');

    const resultSnippet = await page.getByText(/Playwright/i);
    await expect(resultSnippet).toBeVisible();
    await expect(resultSnippet).toHaveCSS('background-color', 'yellow'); // Assuming highlighted terms have a yellow background
  });

  test('should not highlight unrelated terms in result snippets', async ({ page }) => {
    await page.fill('input[name="search"]', 'Playwright');
    await page.click('button[type="submit"]');

    const unrelatedSnippet = await page.getByText(/Selenium/i);
    await expect(unrelatedSnippet).toBeVisible();
    await expect(unrelatedSnippet).not.toHaveCSS('background-color', 'yellow');
  });
});
